actions.script:
found = false; visible = false; request = null; roleList = []
isRaiser = false; isAssignee = false; isWatcher = false; isParty = false
const notAvailable = () => ec.resource.expand('Request ${requestId} is not available', '', {requestId: requestId})
const row = ec.entity.find('mantle.request.Request').condition('requestId', requestId).one()
if (row == null) {
    if (need !== 'check') ec.message.addError(notAvailable())
    return
}
// a confidential case is People's alone (its RequestDetail under People, for its people; impl-people P21): not
// available in Commons, Projects or any app that reads a request through this service, for anyone, and answered as a
// missing request (found false), so not even its existence is told (P21 review)
if (row.requestTypeEnumId === 'RqtHrCase') {
    if (need !== 'check') ec.message.addError(notAvailable())
    return
}
found = true
// a purchase RFQ is Purchasing's alone (QuoteRequestDetail): not available in Commons or Projects (impl-purchasing
// P11, R-PUR-13)
if (row.requestTypeEnumId === 'RqtPurchaseRfq') {
    if (need !== 'check') ec.message.addError(notAvailable())
    return
}
const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo').parameters({
    recordEntityName: 'mantle.request.Request', recordId: requestId, checkOnly: true}).call()
if (ec.message.hasError()) return
visible = info?.recordVisible === true
if (!visible) {
    ec.logger.info(`Request ${requestId} is not visible to user ${ec.user.userId}: ${info?.notVisibleReason || ''}`)
    if (need !== 'check') ec.message.addError(notAvailable())
    return
}
request = row.getMap()
const partyId = ec.user.userAccount?.partyId || null
const cf = ec.entity.conditionFactory
if (partyId) for (const rp of ec.entity.find('mantle.request.RequestParty').condition('requestId', requestId).condition('partyId', partyId)
        .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list()) if (!roleList.includes(rp.roleTypeId)) roleList.push(rp.roleTypeId)
isRaiser = (!!partyId && row.filedByPartyId === partyId) || roleList.includes('Reporter')
isAssignee = roleList.includes('Assignee')
isParty = roleList.length > 0 || isRaiser
isWatcher = roleList.includes('Watcher') || ec.entity.find('mantle.party.communication.RecordFollower')
        .condition('recordEntityName', 'mantle.request.Request').condition('recordId', requestId).condition('userId', ec.user.userId).count() > 0

const lists = ['all', 'raised', 'assigned', 'watching', 'closed']
if (!lists.includes(list)) list = 'all'
rowList = []; rowCount = 0; pageMaxIndex = 0; pageRangeLow = 0; pageRangeHigh = 0
counts = {}
for (const key of lists) counts[key] = 0
const partyId = ec.user.userAccount?.partyId || null
if (!partyId) return
const cf = ec.entity.conditionFactory
const L = (text) => ec.l10n.localize(text)
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const nowMillis = toMillis(ec.user.nowTimestamp)
const fmt = (millis, format) => ec.l10n.format(new Date(Number(millis)), format)

// the slice
const entries = new Map()
const entryOf = (id) => {
    let entry = entries.get(id)
    if (!entry) { entry = {roles: new Set(), follower: false, row: null}; entries.set(id, entry) }
    return entry
}
for (const rp of ec.entity.find('mantle.request.RequestAndParty').condition('partyId', partyId)
        .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list()) {
    const entry = entryOf(rp.requestId)
    entry.roles.add(rp.roleTypeId)
    if (!entry.row) entry.row = rp
}
for (const filed of ec.entity.find('mantle.request.Request').condition('filedByPartyId', partyId).list()) entryOf(filed.requestId).row = filed
for (const follower of ec.entity.find('mantle.party.communication.RecordFollower').condition('recordEntityName', 'mantle.request.Request')
        .condition('userId', ec.user.userId).list()) {
    const id = follower.recordId
    if (entries.has(id)) { entries.get(id).follower = true; continue }
    const request = ec.entity.find('mantle.request.Request').condition('requestId', id).one()
    if (request == null) continue
    const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo').parameters({
        recordEntityName: 'mantle.request.Request', recordId: id, checkOnly: true}).call()
    if (info?.recordVisible !== true) continue
    const entry = entryOf(id)
    entry.row = request
    entry.follower = true
}
const closedOf = (row) => ['ReqCompleted', 'ReqCancelled'].includes(row.statusId)
const openOf = (row) => !closedOf(row)
const rest = {
    all: () => true,
    raised: (row, entry) => row.filedByPartyId === partyId || entry.roles.has('Reporter'),
    assigned: (row, entry) => entry.roles.has('Assignee'),
    watching: (row, entry) => entry.roles.has('Watcher') || entry.follower,
    closed: () => true
}
const statusPart = (key) => key === 'closed' ? closedOf : openOf
// a purchase RFQ is in no Commons list (impl-purchasing P11, R-PUR-13), nor a confidential case (People's, impl-people P21)
const all = Array.from(entries.entries()).filter(([id, entry]) => entry.row != null && !['RqtPurchaseRfq', 'RqtHrCase'].includes(entry.row.requestTypeEnumId)).map(([id, entry]) => ({id: id, entry: entry, row: entry.row}))
for (const key of lists) counts[key] = all.filter((item) => statusPart(key)(item.row) && rest[key](item.row, item.entry)).length

// the find
const statusIds = statusId ? String(statusId).split(',').map((id) => id.trim()).filter((id) => id) : []
const words = text ? String(text).trim().toLowerCase() : ''
const fromMillis = toMillis(dateFrom)
const thruMillis = toMillis(dateThru)
const priorityText = priority != null && String(priority).trim() !== '' ? String(priority).trim() : null
const rows = all.filter((item) => {
    const row = item.row
    if (statusIds.length ? !statusIds.includes(row.statusId) : !statusPart(list)(row)) return false
    if (!rest[list](row, item.entry)) return false
    if (requestTypeEnumId && row.requestTypeEnumId !== requestTypeEnumId) return false
    if (priorityText) {
        const value = row.priority ?? null
        // High 1-3, Normal 4-6, Low 7-9, or one number
        const bands = {high: [1, 3], normal: [4, 6], low: [7, 9]}
        const band = bands[priorityText.toLowerCase()]
        if (band ? !(value != null && value >= band[0] && value <= band[1]) : String(value) !== priorityText) return false
    }
    if (fromMillis != null || thruMillis != null) {
        const date = toMillis(row.requestDate)
        if (date == null || (fromMillis != null && date < fromMillis) || (thruMillis != null && date >= thruMillis)) return false
    }
    if (words && !(String(row.requestName || '').toLowerCase().includes(words) || String(row.description || '').toLowerCase().includes(words)
            || String(item.id).toLowerCase().includes(words))) return false
    return true
})

const sortKey = orderByField ? String(orderByField).replace(/^[+^]/, '') : ''
const desc = sortKey.startsWith('-')
const field = desc ? sortKey.substring(1) : sortKey
const updatedOf = (item) => toMillis(item.row.lastUpdatedStamp) ?? toMillis(item.row.requestDate) ?? 0
const comparators = {
    requestId: (left, right) => String(left.id).localeCompare(String(right.id)),
    requestName: (left, right) => String(left.row.requestName || '').localeCompare(String(right.row.requestName || '')),
    priority: (left, right) => (left.row.priority ?? 99) - (right.row.priority ?? 99) || updatedOf(right) - updatedOf(left),
    statusId: (left, right) => String(left.row.statusId || '').localeCompare(String(right.row.statusId || '')),
    requestDate: (left, right) => (toMillis(left.row.requestDate) ?? 0) - (toMillis(right.row.requestDate) ?? 0),
    lastUpdatedStamp: (left, right) => updatedOf(left) - updatedOf(right)
}
if (comparators[field]) {
    rows.sort(comparators[field])
    if (desc) rows.reverse()
} else {
    // the latest change first
    rows.sort((left, right) => updatedOf(right) - updatedOf(left))
}

rowCount = rows.length
const size = Math.max(1, Math.min(Number(pageSize) || 25, 200))
pageSize = size
pageMaxIndex = rowCount ? Math.floor((rowCount - 1) / size) : 0
pageIndex = Math.min(Math.max(0, Number(pageIndex) || 0), pageMaxIndex)
const page = rows.slice(pageIndex * size, (pageIndex + 1) * size)
pageRangeLow = rowCount ? pageIndex * size + 1 : 0
pageRangeHigh = Math.min((pageIndex + 1) * size, rowCount)
if (!page.length) return

// the decoration: type, status, customer and assignee
const ids = page.map((item) => item.id)
const statusIdsShown = Array.from(new Set(page.map((item) => item.row.statusId).filter((id) => id)))
const colors = ec.service.sync().name('org.moqui.ui.StatusServices.get#StatusColors').parameters({statusIdList: statusIdsShown}).call()?.colors || {}
const statusLabel = (id) => { const item = id ? ec.entity.find('moqui.basic.StatusItem').condition('statusId', id).useCache(true).one() : null; return item ? (item.description || id) : (id || '') }
const enumLabel = (id) => { const item = id ? ec.entity.find('moqui.basic.Enumeration').condition('enumId', id).useCache(true).one() : null; return item ? (item.description || id) : (id || '') }
const byRole = {}
const partyIds = new Set()
for (const rp of ec.entity.find('mantle.request.RequestParty').condition('requestId', 'in', ids).condition('roleTypeId', 'in', ['Customer', 'Assignee'])
        .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).orderBy('-fromDate').list()) {
    const key = rp.requestId + '|' + rp.roleTypeId
    if (!byRole[key]) byRole[key] = rp.partyId
    partyIds.add(rp.partyId)
}
const names = {}
if (partyIds.size) for (const party of ec.entity.find('mantle.party.PartyDetail').condition('partyId', 'in', Array.from(partyIds)).list())
    names[party.partyId] = party.privateOwnerUserId && party.privateOwnerUserId !== ec.user.userId ? party.partyId
        : (party.organizationName || [party.firstName, party.lastName].filter((name) => name).join(' ') || party.pseudoId || party.partyId)
const thisYear = fmt(nowMillis, 'yyyy')
const dateText = (millis) => millis == null ? '' : fmt(millis, fmt(millis, 'yyyy') === thisYear ? 'MMM d' : 'MMM d, yyyy')
for (const item of page) {
    const row = item.row
    const customerId = byRole[item.id + '|Customer'] || null
    const assigneeId = byRole[item.id + '|Assignee'] || null
    const updated = toMillis(row.lastUpdatedStamp)
    rowList.push({requestId: item.id, requestName: row.requestName || item.id, url: '/qapps/Commons/Requests/RequestDetail?requestId=' + encodeURIComponent(item.id),
        requestTypeEnumId: row.requestTypeEnumId || null, typeLabel: enumLabel(row.requestTypeEnumId), statusId: row.statusId || null,
        statusLabel: statusLabel(row.statusId), statusColor: colors[row.statusId] || 'grey-7', priority: row.priority ?? null,
        priorityText: row.priority != null ? String(row.priority) : '', customerPartyId: customerId, customerName: customerId ? (names[customerId] || customerId) : '',
        assigneePartyId: assigneeId, assigneeName: assigneeId ? (names[assigneeId] || assigneeId) : '', isMine: assigneeId === partyId,
        requestDateText: dateText(toMillis(row.requestDate)), updatedText: dateText(updated), roleList: Array.from(item.entry.roles),
        isClosed: closedOf(row)})
}

const L = (text) => ec.l10n.localize(text)
const cf = ec.entity.conditionFactory
const partyId = ec.user.userAccount?.partyId || null
const row = access.request
isRaiser = !!access.isRaiser
isAssignee = !!access.isAssignee
const open = !['ReqCompleted', 'ReqCancelled'].includes(row.statusId)
canSubmit = isRaiser && row.statusId === 'ReqDraft'
canCancel = isRaiser && open
canEdit = isRaiser && row.statusId === 'ReqDraft'
canReassign = isAssignee && open
canAddTask = (access.isParty || isRaiser) && open
canLink = canAddTask
const toMillis = (value) => value == null || value === '' ? null : (/^-?\d+$/.test(String(value)) ? Number(String(value)) : Date.parse(String(value)))
const fmt = (millis, format) => millis == null ? '' : ec.l10n.format(new Date(Number(millis)), format)
const enumLabel = (id) => { const item = id ? ec.entity.find('moqui.basic.Enumeration').condition('enumId', id).useCache(true).one() : null; return item ? (item.description || id) : '' }
const roleName = (id) => { const role = id ? ec.entity.find('mantle.party.RoleType').condition('roleTypeId', id).useCache(true).one() : null; return role ? (role.description || id) : (id || '') }
const partyName = (party) => party ? (party.organizationName || [party.firstName, party.lastName].filter((name) => name).join(' ') || party.pseudoId || party.partyId) : null

// the status-bar: the stages, and the requester's Submit and Cancel
stageStatusIds = ['ReqDraft', 'ReqSubmitted', 'ReqReviewed', 'ReqInProgress', 'ReqCompleted']
allowedStatusIds = []
if (canSubmit) allowedStatusIds.push('ReqSubmitted')
if (canCancel) allowedStatusIds.push('ReqCancelled')
const statusColor = row.statusId ? (ec.service.sync().name('org.moqui.ui.StatusServices.get#StatusColors')
        .parameters({statusIdList: [row.statusId]}).call()?.colors?.[row.statusId] || 'grey-7') : 'grey-7'

const seenRoles = new Set()
const rps = Array.from(ec.entity.find('mantle.request.RequestParty').condition('requestId', requestId)
        .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).orderBy('roleTypeId').orderBy('-fromDate').list())
        .filter((rp) => { const key = rp.partyId + '|' + rp.roleTypeId; if (seenRoles.has(key)) return false; seenRoles.add(key); return true })
const ids = Array.from(new Set(rps.map((rp) => rp.partyId).concat(row.filedByPartyId ? [row.filedByPartyId] : [])))
const parties = {}
if (ids.length) for (const party of ec.entity.find('mantle.party.PartyDetail').condition('partyId', 'in', ids).list()) parties[party.partyId] = party
// the users among them, so an avatar shows the user's photo
const userIds = {}
if (ids.length) for (const account of ec.entity.find('moqui.security.UserAccount').condition('partyId', 'in', ids)
        .selectField('partyId,userId').disableAuthz().list()) userIds[account.partyId] = account.userId
const nameOf = (id) => {
    const party = parties[id]
    if (!party) return id
    return party.privateOwnerUserId && party.privateOwnerUserId !== ec.user.userId ? id : partyName(party)
}
const order = {Customer: 1, Reporter: 2, Assignee: 3, Watcher: 5}
rps.sort((left, right) => (order[left.roleTypeId] || 4) - (order[right.roleTypeId] || 4))
partyList = rps.map((rp) => ({partyId: rp.partyId, name: nameOf(rp.partyId), roleTypeId: rp.roleTypeId, roleText: roleName(rp.roleTypeId),
    isMe: rp.partyId === partyId, sinceText: fmt(toMillis(rp.fromDate), 'MMM d, yyyy'),
    url: parties[rp.partyId] ? '/qapps/Commons/Contacts/ContactDetail?partyId=' + encodeURIComponent(rp.partyId) : null}))
const first = (role) => rps.find((rp) => rp.roleTypeId === role) || null
const customer = first('Customer')
const assignee = first('Assignee')
const statusItem = row.statusId ? ec.entity.find('moqui.basic.StatusItem').condition('statusId', row.statusId).useCache(true).one() : null
const priority = row.priority ?? null
request = Object.assign({}, row, {typeLabel: enumLabel(row.requestTypeEnumId), resolutionLabel: enumLabel(row.requestResolutionEnumId),
    statusLabel: statusItem ? statusItem.description : (row.statusId || ''), statusColor: statusColor,
    priorityText: priority == null ? '' : (priority <= 3 ? L('High') : priority <= 6 ? L('Normal') : L('Low')) + ' (' + priority + ')',
    customerPartyId: customer?.partyId || null, customerName: customer ? nameOf(customer.partyId) : '',
    customerUserId: customer ? (userIds[customer.partyId] || null) : null,
    assigneePartyId: assignee?.partyId || null, assigneeName: assignee ? nameOf(assignee.partyId) : '',
    assigneeUserId: assignee ? (userIds[assignee.partyId] || null) : null,
    filedByName: row.filedByPartyId ? nameOf(row.filedByPartyId) : '',
    requestDateText: fmt(toMillis(row.requestDate), 'MMM d, yyyy h:mm a'), responseRequiredText: fmt(toMillis(row.responseRequiredDate), 'MMM d, yyyy h:mm a'),
    responseRequiredEdit: fmt(toMillis(row.responseRequiredDate), 'yyyy-MM-dd HH:mm'),
    updatedText: fmt(toMillis(row.lastUpdatedStamp), 'MMM d, yyyy h:mm a'), description: row.description || '',
    isWatcher: !!access.isWatcher, roleList: access.roleList || []})

const taskIds = Array.from(ec.entity.find('mantle.request.RequestWorkEffort').condition('requestId', requestId).list()).map((link) => link.workEffortId)
// a maintenance work order only for one Maintenance admits to it (impl-maintenance P4, F69, F78: its reporter follows it in
// the request's Maintenance summary, never its time or people)
const maintenanceAccess = ec.resource.script('component://mr-mantle/service/mantle/work/MaintenanceAccess.js')
const tasks = taskIds.length ? Array.from(ec.resource.script('component://mr-boss/service/ironstone/projects/HiddenItems.js').without(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', taskIds)
        .condition('workEffortTypeEnumId', 'WetTask')).orderBy('estimatedCompletionDate').list())
        .filter((task) => task.purposeEnumId !== 'WepMaintenance' || !maintenanceAccess.workHidden(task.workEffortId, partyId))
        .map((task) => task.getMap()) : []
taskList = tasks.length ? (ec.service.sync().name('ironstone.commons.TaskServices.decorate#TaskRows').parameters({taskList: tasks}).call()?.rowList || []) : []

// records other than tasks: a wiki page through its own join, anything else through RequestRecord
linkedRecordList = []
const seenLinks = new Set()
const addLink = (recordEntityName, recordId) => {
    const key = recordEntityName + '|' + recordId
    if (!recordEntityName || !recordId || seenLinks.has(key)) return
    seenLinks.add(key)
    ec.message.pushErrors()
    let shown = false
    try {
        shown = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo').parameters({recordEntityName: recordEntityName,
            recordId: recordId, checkOnly: true}).call()?.recordVisible === true
    } catch (err) { shown = false } finally { ec.message.clearErrors(); ec.message.popErrors() }
    if (!shown) return
    linkedRecordList.push({recordEntityName: recordEntityName, recordId: recordId, canRemove: canLink})
}
for (const link of ec.entity.find('mantle.request.WikiPageRequest').condition('requestId', requestId).list())
    addLink('moqui.resource.wiki.WikiPage', link.wikiPageId)
for (const link of ec.entity.find('mantle.request.RequestRecord').condition('requestId', requestId).orderBy('linkedDate').list())
    addLink(link.recordEntityName, link.recordId)

// only what the form gave: an absent field is left as it is
const fields = {requestId: requestId}
if (requestName != null) fields.requestName = String(requestName).trim()
if (requestTypeEnumId) fields.requestTypeEnumId = requestTypeEnumId
if (priority != null) fields.priority = priority
if (description != null) fields.description = description
if (responseRequiredDate != null) fields.responseRequiredDate = responseRequiredDate
// a support case's due date is its service level's (impl-customer-service P2, F64)
if (responseRequiredDate != null) ec.resource.script('component://mr-boss/service/ironstone/customerservice/CaseGuard.js').refuseDue(requestId)
if (customerPartyId) fields.customerPartyId = customerPartyId
ec.service.sync().name('mantle.request.RequestServices.update#Request').parameters(fields).call()

created = false
const L = (text) => ec.l10n.localize(text)
const access = ec.service.sync().name('ironstone.commons.RequestServices.get#RequestAccess').parameters({requestId: requestId, need: 'view'}).call()
if (ec.message.hasError()) return
if (!(access.isParty || access.isRaiser)) { ec.message.addError(L('Only the request\'s people may link a record to it')); return }
if (['ReqCompleted', 'ReqCancelled'].includes(access.request.statusId)) { ec.message.addError(L('This request is closed')); return }
let entityName = recordEntityName || null
let id = recordId || null
if (!entityName && record) {
    const text = String(record)
    const at = text.lastIndexOf('|')
    if (at > 0) { entityName = text.substring(0, at); id = text.substring(at + 1) }
}
if (!entityName || !id) { ec.message.addError(L('Choose the record to link')); return }
if (entityName === 'mantle.request.Request' && id === requestId) { ec.message.addError(L('A request is not linked to itself')); return }
// a warranty claim's evidence (its serial, order, invoice, agreement) through Mantle's WarrantyServices, which checks it
// and moves the claim's revision (impl-customer-service F185)
if (access.request.requestTypeEnumId === 'RqtWarranty' && ['mantle.product.asset.Asset', 'mantle.order.OrderHeader',
        'mantle.account.invoice.Invoice', 'mantle.party.agreement.Agreement'].includes(entityName)) {
    const claimOut = ec.service.sync().name('mantle.request.WarrantyServices.link#ClaimEvidence').parameters({
        requestId: requestId, recordEntityName: entityName, recordId: id}).call()
    if (ec.message.hasError()) return
    created = !!claimOut?.changed
    message = created ? L('Linked; the claim is at a new revision') : L('It was linked already')
    return
}
const out = ec.service.sync().name('mantle.request.RequestServices.link#RequestRecord').parameters({requestId: requestId,
    recordEntityName: entityName, recordId: id}).call()
if (ec.message.hasError()) return
created = !!out?.created
message = created ? L('Linked') : L('It was linked already')

unlinked = false
const L = (text) => ec.l10n.localize(text)
const access = ec.service.sync().name('ironstone.commons.RequestServices.get#RequestAccess').parameters({requestId: requestId, need: 'view'}).call()
if (ec.message.hasError()) return
if (!(access.isParty || access.isRaiser)) { ec.message.addError(L('Only the request\'s people may link a record to it')); return }
if (['ReqCompleted', 'ReqCancelled'].includes(access.request.statusId)) { ec.message.addError(L('This request is closed')); return }
// a warranty claim's evidence through Mantle's WarrantyServices, which moves the claim's revision (F185)
if (access.request.requestTypeEnumId === 'RqtWarranty' && ['mantle.product.asset.Asset', 'mantle.order.OrderHeader',
        'mantle.account.invoice.Invoice', 'mantle.party.agreement.Agreement'].includes(recordEntityName)) {
    const claimOut = ec.service.sync().name('mantle.request.WarrantyServices.unlink#ClaimEvidence').parameters({
        requestId: requestId, recordEntityName: recordEntityName, recordId: recordId}).call()
    if (ec.message.hasError()) return
    unlinked = !!claimOut?.changed
    message = L(unlinked ? 'Taken off the record; the claim is at a new revision' : 'It was not linked')
    return
}
const out = ec.service.sync().name('mantle.request.RequestServices.unlink#RequestRecord').parameters({requestId: requestId,
    recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError()) return
unlinked = !!out?.unlinked
message = L(unlinked ? 'Taken off the record' : 'It was not linked')
